import unittest

from tiny_filter_guided import keep_nonempty, keep_positive


class TinyFilterGuidedTests(unittest.TestCase):
    def test_worked_positive_example(self):
        self.assertEqual(keep_positive([-2, 3, 0, 4]), [3, 4])

    def test_keeps_nonempty_in_order(self):
        self.assertEqual(keep_nonempty(["", "agent", "", "tool"]), ["agent", "tool"])

    def test_empty_input(self):
        self.assertEqual(keep_nonempty([]), [])

    def test_all_empty(self):
        self.assertEqual(keep_nonempty(["", ""]), [])

    def test_boundary_one_character(self):
        self.assertEqual(keep_nonempty(["a", "", "b"]), ["a", "b"])


if __name__ == "__main__":
    unittest.main(verbosity=2)

import unittest

from tiny_filter_cold import keep_long_enough


class TinyFilterColdTests(unittest.TestCase):
    def test_keeps_only_length_three_or_more(self):
        self.assertEqual(keep_long_enough(["a", "tool", "AI", "run"]), ["tool", "run"])

    def test_empty_input(self):
        self.assertEqual(keep_long_enough([]), [])

    def test_boundary_lengths(self):
        self.assertEqual(keep_long_enough(["", "a", "ab", "abc", "abcd"]), ["abc", "abcd"])

    def test_repeats_are_preserved(self):
        self.assertEqual(keep_long_enough(["run", "run", "x"]), ["run", "run"])

    def test_order_is_preserved(self):
        self.assertEqual(keep_long_enough(["last", "first", "mid"]), ["last", "first", "mid"])


if __name__ == "__main__":
    unittest.main(verbosity=2)

