import unittest

from tiny_count_guided import count_events, count_fruit


class TinyCountGuidedTests(unittest.TestCase):
    def test_worked_fruit_example(self):
        self.assertEqual(count_fruit(["apple", "pear", "apple"]), {"apple": 2, "pear": 1})

    def test_counts_repeated_events(self):
        self.assertEqual(count_events(["ok", "error", "ok"]), {"ok": 2, "error": 1})

    def test_empty_input(self):
        self.assertEqual(count_events([]), {})

    def test_single_event(self):
        self.assertEqual(count_events(["queued"]), {"queued": 1})

    def test_first_seen_order(self):
        result = count_events(["b", "a", "b", "c"])
        self.assertEqual(list(result), ["b", "a", "c"])


if __name__ == "__main__":
    unittest.main(verbosity=2)

import unittest

from tiny_count_cold import count_final_chars


class TinyCountColdTests(unittest.TestCase):
    def test_counts_final_characters(self):
        self.assertEqual(count_final_chars(["run", "tool", "plan"]), {"n": 2, "l": 1})

    def test_empty_input(self):
        self.assertEqual(count_final_chars([]), {})

    def test_empty_words_are_ignored(self):
        self.assertEqual(count_final_chars(["", "a", "", "b"]), {"a": 1, "b": 1})

    def test_repeated_final_character(self):
        self.assertEqual(count_final_chars(["run", "plan", "green"]), {"n": 3})

    def test_first_seen_order(self):
        result = count_final_chars(["cat", "dog", "ant", "bee"])
        self.assertEqual(list(result), ["t", "g", "e"])


if __name__ == "__main__":
    unittest.main(verbosity=2)
